# Event-log traversal: filter by type/severity, sequence-pattern match, sessionize.
events = [{'ts': '10:01', 'type': 'login', 'sev': 'INFO', 'msg': 'ok'}, {'ts': '10:02', 'type': 'error', 'sev': 'WARN', 'msg': 'slow'}, {'ts': '10:03', 'type': 'purchase', 'sev': 'INFO', 'msg': 'bought'}]
def seq_match(evts, pattern):
    # pattern: list of types that must appear in order (not necessarily adjacent)
    hits, pi = [], 0
    cur = []
    for e in evts:
        if e["type"] == pattern[pi]:
            cur.append(e); pi += 1
            if pi == len(pattern):
                hits.append(cur); cur = []; pi = 0
    return hits
sev = "WARN"
print(f"events with severity >= {sev}:")
for e in events:
    if e["sev"] >= sev: print(f"  {e['ts']} {e['type']:8} {e['sev']} {e['msg']}")
pat = ['login','purchase']
print("pattern", pat, "matched", len(seq_match(events, pat)), "time(s)")

